package com.smartspend.controller;
import com.smartspend.dao.TransactionDAO;import com.smartspend.model.Transaction;import com.smartspend.util.*;import javafx.geometry.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.FileChooser;import java.io.*;import java.time.*;import java.util.*;
public class ReportsView extends VBox {private final int uid=Session.getUser().getId();private final TransactionDAO dao=new TransactionDAO();private final TextArea preview=new TextArea();private String csv="";public ReportsView(){setPadding(new Insets(5,30,30,30));setSpacing(15);ComboBox<Integer>year=new ComboBox<>();year.getItems().addAll(2025,2026,2027);year.setValue(LocalDate.now().getYear());ComboBox<Integer>month=new ComboBox<>();for(int i=1;i<=12;i++)month.getItems().add(i);month.setValue(LocalDate.now().getMonthValue());Button generate=UI.button("Generate Report");Button export=UI.ghost("Export CSV");generate.setOnAction(e->generate(year.getValue(),month.getValue()));export.setOnAction(e->export());preview.setEditable(false);preview.setPrefHeight(400);getChildren().addAll(UI.title("Reports"),UI.subtitle("Generate and export a monthly financial report."),new HBox(10,new Label("Year"),year,new Label("Month"),month,generate,export),preview);generate(year.getValue(),month.getValue());}private void generate(int y,int m){List<Transaction>t=dao.findByUser(uid);double in=0,ex=0;Map<String,Double>cat=new LinkedHashMap<>();for(Transaction x:t)if(x.getTransactionDate().getYear()==y&&x.getTransactionDate().getMonthValue()==m){if(x.getType().equals("INCOME"))in+=x.getAmount();else{ex+=x.getAmount();cat.merge(x.getCategoryName(),x.getAmount(),Double::sum);}}StringBuilder s=new StringBuilder("Metric,Amount\nTotal Income,").append(in).append("\nTotal Expenses,").append(ex).append("\nSavings,").append(in-ex).append("\n\nCategory,Amount\n");cat.forEach((k,v)->s.append(k).append(',').append(v).append('\n'));csv=s.toString();preview.setText(csv);}private void export(){FileChooser f=new FileChooser();f.setInitialFileName("smartspend-report.csv");File file=f.showSaveDialog(getScene().getWindow());if(file!=null)try{java.nio.file.Files.writeString(file.toPath(),csv);UI.alert(getScene().getWindow(),"Export complete","CSV report saved to "+file.getAbsolutePath());}catch(Exception e){UI.error(getScene().getWindow(),e.getMessage());}}}
